create table if not exists public.invoices (
 id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, placement_id uuid references public.placements(id) on delete set null, client_id uuid not null references public.clients(id) on delete restrict, number text not null, status text not null default 'draft' check(status in ('draft','sent','part_paid','paid','overdue','void')), currency char(3) not null default 'GBP', subtotal numeric(14,2) not null default 0, tax_rate numeric(6,3) not null default 0, tax_amount numeric(14,2) not null default 0, total numeric(14,2) not null default 0, amount_paid numeric(14,2) not null default 0, amount_due numeric(14,2) generated always as (greatest(total-amount_paid,0)) stored, issue_date date, due_date date, sent_at timestamptz, paid_at timestamptz, voided_at timestamptz, notes text, external_provider text, external_id text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id,number));
create table if not exists public.invoice_adjustments (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, invoice_id uuid not null references public.invoices(id) on delete cascade, kind text not null check(kind in ('payment','credit','refund','write_off','correction')), amount numeric(14,2) not null check(amount>0), reason text not null, reference text, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.saas_plans (code text primary key, name text not null, monthly_price_gbp numeric(10,2) not null default 0, recruiter_limit int, active_job_limit int, candidate_limit int, automation_limit int, features jsonb not null default '{}'::jsonb, active boolean not null default true);
insert into public.saas_plans(code,name,monthly_price_gbp,recruiter_limit,active_job_limit,candidate_limit,automation_limit,features) values ('starter','Starter',49,2,10,2500,5,'{"client_portal":true,"ai_screening":true}'::jsonb),('growth','Growth',99,5,40,15000,25,'{"client_portal":true,"ai_screening":true,"automations":true}'::jsonb),('scale','Scale',199,15,150,100000,100,'{"client_portal":true,"ai_screening":true,"automations":true,"priority_support":true}'::jsonb) on conflict(code) do update set name=excluded.name,monthly_price_gbp=excluded.monthly_price_gbp,recruiter_limit=excluded.recruiter_limit,active_job_limit=excluded.active_job_limit,candidate_limit=excluded.candidate_limit,automation_limit=excluded.automation_limit,features=excluded.features;
create table if not exists public.company_subscriptions (company_id uuid primary key references public.companies(id) on delete cascade, plan_code text not null references public.saas_plans(code), status text not null default 'trialing' check(status in ('trialing','active','past_due','cancelled','suspended')), trial_ends_at timestamptz, current_period_start timestamptz, current_period_end timestamptz, provider text, provider_customer_id text, provider_subscription_id text, cancel_at_period_end boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.companies add column if not exists slug text; alter table public.companies add column if not exists onboarding_completed_at timestamptz; alter table public.companies add column if not exists billing_email text; create unique index if not exists companies_slug_unique on public.companies(lower(slug)) where slug is not null;
alter table public.invoices enable row level security; alter table public.invoice_adjustments enable row level security; alter table public.saas_plans enable row level security; alter table public.company_subscriptions enable row level security;
create policy invoices_tenant_select on public.invoices for select to authenticated using (company_id=(select company_id from public.profiles where id=(select auth.uid())));
create policy invoices_tenant_insert on public.invoices for insert to authenticated with check (company_id=(select company_id from public.profiles where id=(select auth.uid())) and (select role from public.profiles where id=(select auth.uid())) in ('owner','manager'));
create policy invoices_tenant_update on public.invoices for update to authenticated using (company_id=(select company_id from public.profiles where id=(select auth.uid())) and (select role from public.profiles where id=(select auth.uid())) in ('owner','manager')) with check (company_id=(select company_id from public.profiles where id=(select auth.uid())));
create policy invoice_adjustments_tenant_select on public.invoice_adjustments for select to authenticated using (company_id=(select company_id from public.profiles where id=(select auth.uid())));
create policy invoice_adjustments_tenant_insert on public.invoice_adjustments for insert to authenticated with check (company_id=(select company_id from public.profiles where id=(select auth.uid())) and (select role from public.profiles where id=(select auth.uid())) in ('owner','manager'));
create policy saas_plans_read on public.saas_plans for select to authenticated using(active=true);
create policy subscriptions_tenant_read on public.company_subscriptions for select to authenticated using(company_id=(select company_id from public.profiles where id=(select auth.uid())));
grant select,insert,update on public.invoices to authenticated; grant select,insert on public.invoice_adjustments to authenticated; grant select on public.saas_plans,public.company_subscriptions to authenticated;
